    @SneakyThrows
    public static void main(String[] args) {
        BufferedWriter bw = new BufferedWriter(new FileWriter(MyIconPath));
        bw.write(".mi {\n" +
                "    display: inline-block;\n" +
                "    align-items: center;\n" +
                "    justify-content: center;\n" +
                "    width: 1em;\n" +
                "    height: 1em;\n" +
                "    font-size: inherit;\n" +
                "    color: inherit;\n" +
                "    vertical-align: -0.15em;\n" +
                "    line-height: 1rem;\n" +
                "}\n" +
                ".mi::before{\n" +
                "    width: 100%;\n" +
                "    height: 100%;\n" +
                "    content: '';\n" +
                "    display: inline-block;\n" +
                "}");
        bw.flush();
        icons.forEach((k,v)->{
            if(StrUtil.isNotBlank(k)){
                try {
                    bw.newLine();
                    v=removeAttributes(v).replace("\"","'");
                    v=v.replace("<svg","<svg fill='currentColor'");
                    v=v.replace("<","%3C");
                    v=v.replace(">","%3E");
                    bw.write(".mi-"+k+" {\n" +
                            "    background: currentColor;\n" +
                            "    mask: url(\"data:image/svg+xml,"+v+"\");\n" +
                            "}");
                    bw.flush();
                } catch (IOException e) {
                }
            }
        });
        bw.close();
    }


    /**
     * 移除指定的 SVG 属性
     */
    private static String removeAttributes(String svgContent) {
        for (String attribute : attributesToRemove) {
            String regex = "\\s+" + Pattern.quote(attribute) + "=\"[^\"]*\"";
            svgContent = svgContent.replaceAll(regex, "");
        }
        return svgContent;
    }
